{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    for seg in segments:
        if not all(k in seg for k in ('name','importance','minimum','capacity')):
            raise ValueError("Missing field")
    sum_min = sum(seg['minimum'] for seg in segments)
    sum_cap = sum(seg['capacity'] for seg in segments)
    if budget < sum_min or budget > sum_cap:
        raise ValueError("Budget out of range")
    n = len(segments)
    allocations = [seg['minimum'] for seg in segments]
    remaining = budget - sum_min
    while remaining > 0:
        best_idx = -1
        best_ratio = -1.0
        for i in range(n):
            if allocations[i] < segments[i]['capacity']:
                ratio = segments[i]['importance'] / (allocations[i] + 1)
                if ratio > best_ratio:
                    best_ratio = ratio
                    best_idx = i
        if best_idx == -1:
            raise ValueError("Cannot allocate more")
        allocations[best_idx] += 1
        remaining -= 1
    by_name = {segments[i]['name']: allocations[i] for i in range(n)}
    total = sum(allocations)
    return {'allocations': allocations, 'by_name': by_name, 'total': total}
